scripts.script:
local Rayfield = loadstring(game:HttpGet('https://sirius.menu/rayfield'))()

local Window = Rayfield:CreateWindow({
    Name = "Random by A.Z.",
    LoadingTitle = "Loading...",
    LoadingSubtitle = "AcelestuZ",
    ConfigurationSaving = {Enabled = false},
    KeySystem = false
})

local Main = Window:CreateTab("Actions", 4483362458)

local function ExecuteTP(pos, obj)
    local p = game.Players.LocalPlayer.Character.HumanoidRootPart
    p.CFrame = CFrame.new(pos)
    task.wait(1)
    if obj then
        firetouchinterest(p, obj, 0)
        firetouchinterest(p, obj, 1)
    end
end

Main:CreateButton({
    Name = "1. Lobby Teleporter",
    Callback = function()
        ExecuteTP(Vector3.new(-1083, 31, -2007), workspace["Game Teleporter"])
    end,
})

Main:CreateButton({
    Name = "2. Lobby / Game Start",
    Callback = function()
        ExecuteTP(Vector3.new(-557, 12, -120), nil)
    end,
})

Main:CreateButton({
    Name = "3. Enter Game (Portal 426)",
    Callback = function()
        local target = workspace:GetChildren()[426]
        local portal = target and target:FindFirstChild("Portal")
        ExecuteTP(Vector3.new(-316, 10, -331), portal)
    end,
})

Main:CreateButton({
    Name = "4. Get Badge (Part 78)",
    Callback = function()
        local target = workspace:GetChildren()[78]
        ExecuteTP(Vector3.new(174, 62, 115), target)
    end,
})

Main:CreateButton({
    Name = "Now return to previous game (Stranger Things Tales From 85 (Event) and click this button",
    Callback = function()
        ExecuteTP(Vector3.new(-1093, 31, -2008), nil)
    end,
})

local Settings = Window:CreateTab("Settings", 4483362458)

Settings:CreateButton({
    Name = "Full Bright & No Fog",
    Callback = function()
        game.Lighting.Brightness = 2
        game.Lighting.ClockTime = 14
        game.Lighting.FogEnd = 100000
    end,
})

Settings:CreateKeybind({
    Name = "Toggle UI",
    CurrentKeybind = "RightShift",
    HoldToInteract = false,
    Callback = function()
        Rayfield:ToggleUI()
    end,
})
